function updateCrashImpact(dt){crashElapsed+=dt;const duration=1.05,progress=Math.min(1,crashElapsed/duration),shake=Math.exp(-5*crashElapsed)*(1-progress),slowDt=dt*.16;for(const mark of marks){mark.position.z+=speed*slowDt;if(mark.position.z>16)mark.position.z-=363}grassField.position.z+=speed*slowDt;for(const object of scenery){object.position.z+=speed*slowDt;if(object.position.z>28)object.position.z-=342}for(const obstacle of obstacleGroups){if(obstacle!==crashObstacle)obstacle.position.z+=speed*slowDt}playerRoot.position.set(crashCarPosition.x+Math.sin(crashElapsed*58)*.16*shake,crashCarPosition.y+Math.abs(Math.sin(crashElapsed*38))*.12*shake,crashCarPosition.z);playerRoot.rotation.z=Math.sin(crashElapsed*52)*.12*shake;crashObstacle.position.addScaledVector(crashObstacleVelocity,dt);crashObstacleVelocity.y-=9.8*dt;crashObstacle.rotation.x+=crashObstacleAngularVelocity.x*dt;crashObstacle.rotation.y+=crashObstacleAngularVelocity.y*dt;crashObstacle.rotation.z+=crashObstacleAngularVelocity.z*dt;if(crashObstacle.position.y<crashObstaclePosition.y&&crashObstacleVelocity.y<0){crashObstacle.position.y=crashObstaclePosition.y;if(crashObstacleVelocity.y< -1){crashObstacleVelocity.y*=-.22;crashObstacleVelocity.x*=.55;crashObstacleVelocity.z*=.55;crashObstacleAngularVelocity.multiplyScalar(.58)}else{crashObstacleVelocity.set(0,0,0);crashObstacleAngularVelocity.multiplyScalar(.82)}}renderer.domElement.style.transform=`translate(${Math.sin(crashElapsed*64)*12*shake}px,${Math.cos(crashElapsed*57)*8*shake}px)`;if(crashElapsed>=duration){playerRoot.position.copy(crashCarPosition);playerRoot.rotation.set(0,0,0);crashObstacle=null;renderer.domElement.style.transform='';finish()}}
function finish(){mode='over';stopEngine();$('#hud').classList.remove('on');const n=Math.floor(distance);lastScore=n;localStorage.setItem(CONFIG.storage.lastDistance,String(lastScore));recordCarScore(selected,n);if(n>best){best=n;localStorage.setItem(CONFIG.storage.bestDistance,String(best));$('#best').textContent=String(best).padStart(3,'0');$('#modalEyebrow').textContent='New personal best'}else $('#modalEyebrow').textContent='Run over';updateScoreSummary();$('#modalTitle').textContent=n>0?`${n} m`:'Crash!';$('#modalText').textContent='Watch a rewarded ad to continue this run, or go back to the start.';$('#againBtn').textContent='Watch ad to continue';$('#modal').classList.remove('hidden')}
async function continueAfterRewardedAd(){const showAd=window.showRewardedAd;if(typeof showAd!=='function'){$('#modalText').textContent='Rewarded ads are unavailable right now. You can go back to the start.';return}const button=$('#againBtn');button.disabled=true;button.textContent='Loading ad…';try{const result=await showAd();if(result===true||result?.rewarded===true){mode='playing';paused=false;$('#modal').classList.add('hidden');$('#hud').classList.add('on');$('#pauseBtn').textContent='Ⅱ  Pause';if(!audioSuspended){const playback=engineAudio.play();if(playback?.catch)playback.catch(()=>{})}}else{$('#modalText').textContent='The ad was not completed, so this run cannot continue yet.';button.textContent='Watch ad to continue'}}catch(error){console.warn('Rewarded ad failed',error);$('#modalText').textContent='The rewarded ad could not be shown. Please try again or go back to the start.';button.textContent='Watch ad to continue'}finally{button.disabled=false}}
function togglePause(){if(mode!=='playing')return;paused=!paused;if(paused)holdBoost=false;$('#pauseBtn').textContent=paused?'▶  Resume':'Ⅱ  Pause';$('#pauseBtn').classList.toggle('resume-state',paused);$('#pauseBtn').setAttribute('aria-label',paused?'Resume':'Pause');if(paused){engineAudio.pause();$('#modal').classList.add('paused');$('#modalEyebrow').textContent='Run paused';$('#modalTitle').textContent='Take a breather';$('#modalText').textContent=`You've covered ${Math.floor(distance)} metres. Ready when you are.`;$('#againBtn').textContent='Resume run  ↗';$('#modal').classList.remove('hidden')}else{if(!audioSuspended){const playback=engineAudio.play();if(playback?.catch)playback.catch(()=>{})};$('#modal').classList.remove('paused');$('#modal').classList.add('hidden')}}
$('#startBtn').addEventListener('click',()=>{if(hasChosenCar)begin();else showGarage()});$('#openGarageBtn').addEventListener('click',showGarage);$('#garageBackBtn').addEventListener('click',showStartPage);$('#confirmCarBtn').addEventListener('click',confirmSelectedCar);$('#againBtn').onclick=()=>{if(paused){paused=false;$('#modal').classList.remove('paused');$('#modal').classList.add('hidden');$('#pauseBtn').textContent='Ⅱ  Pause';$('#pauseBtn').classList.remove('resume-state');$('#pauseBtn').setAttribute('aria-label','Pause')}else if(mode==='over')continueAfterRewardedAd();else begin()};$('#pauseBtn').onclick=togglePause;$('#garageBtn').onclick=()=>{paused=false;$('#modal').classList.remove('paused');$('#modal').classList.add('hidden');$('#hud').classList.remove('on');$('#againBtn').textContent='Drive again  ↗';showStartPage()};
$('#againBtn').addEventListener('click',()=>{if(paused){if(!audioSuspended){const playback=engineAudio.play();if(playback?.catch)playback.catch(()=>{})}}},{capture:true});

let perfWindow=0,perfFrames=0;function animate(t){requestAnimationFrame(animate);const dt=Math.min((t-last)/1000||0,.05);last=t;updateClimate(dt);updatePowerVisuals(t);updateSpeedLines(mode==='playing'&&!paused?dt:0);if(mode==='crash')updateCrashImpact(dt);if(mode==='countdown'&&!audioSuspended){countdownTime+=dt;if(countdownTime<CONFIG.gameplay.countdownSeconds)$('#countdown').textContent=String(CONFIG.gameplay.countdownSeconds-Math.floor(countdownTime));else if(countdownTime<CONFIG.gameplay.countdownSeconds+CONFIG.gameplay.countdownGoDuration){stopVroom();$('#countdown').textContent='GO'}else{engineStartAudio.pause();mode='playing';$('#countdown').hidden=true;if(!audioSuspended){const playback=engineAudio.play();if(playback?.catch)playback.catch(()=>{})}}}
 if(mode==='playing'&&!paused){const poweredBefore=powerTime>0;powerTime=Math.max(0,powerTime-dt);if(poweredBefore&&powerTime===0)nextPowerSpawn=distance+CONFIG.gameplay.powerRespawnAfterUse;const runSpeed=driveSpeed();updateThrownObstacles(dt);distance+=runSpeed*dt*CONFIG.gameplay.runDistanceFactor;while(distance>=nextPowerSpawn){nextPowerSpawn+=CONFIG.gameplay.powerSpawnInterval;spawnSpeedPower()}updateSpeedEvents();$('#distance').textContent=String(Math.floor(distance)).padStart(3,'0');const previousX=playerRoot.position.x;playerRoot.position.x=THREE.MathUtils.damp(playerRoot.position.x,(targetLane-1)*CONFIG.gameplay.laneSpacing,CONFIG.gameplay.laneChangeDamping,dt);const lateralDelta=playerRoot.position.x-previousX;lane=targetLane;if(Math.abs(lateralDelta)>.003){skidClock+=dt;if(skidClock>.035){emitSkidMarks(lateralDelta);skidClock=0}}else skidClock=0;updateEffects(dt);spawnClock+=dt;if(spawnClock>Math.max(CONFIG.gameplay.obstacleSpawnMinimumInterval,CONFIG.gameplay.obstacleSpawnStartDistance-distance*CONFIG.gameplay.obstacleSpawnDistanceFactor)){spawnClock=0;spawnObstacle()}
  if(jumpTime>0){jumpTime+=dt;const p=Math.min(1,jumpTime/CONFIG.gameplay.jumpDuration);playerRoot.position.y=Math.sin(p*Math.PI)*CONFIG.gameplay.jumpHeight;playerRoot.rotation.x=jumpMode==='flip'?p*Math.PI*CONFIG.gameplay.jumpFlipRotations:0;if(p>=1){jumpTime=0;playerRoot.position.y=0;playerRoot.rotation.x=0}}
  for(const m of marks){m.position.z+=runSpeed*dt;if(m.position.z>16)m.position.z-=363}
  grassField.position.z+=runSpeed*dt;if(grassField.position.z>20)grassField.position.z-=360;
  for(const o of scenery){o.position.z+=runSpeed*dt;if(o.position.z>28)o.position.z-=342}
  if(playerCollisionBounds)playerCollisionBox.copy(playerCollisionBounds).translate(playerRoot.position);
  for(let i=speedPowers.length-1;i>=0;i--){const pickup=speedPowers[i];pickup.position.z+=runSpeed*dt;pickup.position.y=pickup.userData.baseY+Math.sin(t*.004+pickup.userData.phase)*.12;pickup.rotation.y+=dt*1.7;if(playerCollisionBounds&&pickup.userData.collisionBounds){movingCollisionBox.copy(pickup.userData.collisionBounds).translate(pickup.position);if(playerCollisionBox.intersectsBox(movingCollisionBox)){collectSpeedPower(pickup,i);continue}}if(pickup.position.z>17){scene.remove(pickup);speedPowers.splice(i,1)}}
  for(let i=obstacleGroups.length-1;i>=0;i--){const o=obstacleGroups[i];o.position.z+=runSpeed*dt;if(!o.userData.hit&&jumpTime===0&&playerCollisionBounds&&o.userData.collisionBounds){movingCollisionBox.copy(o.userData.collisionBounds).translate(o.position);if(playerCollisionBox.intersectsBox(movingCollisionBox)){o.userData.hit=true;if(powerTime>0){throwPoweredObstacle(o,i);continue}triggerCrash(o);break}}if(o.position.z>17){scene.remove(o);obstacleGroups.splice(i,1)}}
 }
 if(mode==='garage'){playerRoot.position.x=Math.sin(t*.0004)*.18;camera.position.x=THREE.MathUtils.damp(camera.position.x,0,3,dt)}else if(mode==='playing'){camera.position.x=THREE.MathUtils.damp(camera.position.x,playerRoot.position.x,7,dt)}camera.lookAt(camera.position.x,.8,-4)
 renderer.render(scene,camera);perfWindow+=dt;perfFrames++;if(perfWindow>2){const fps=perfFrames/perfWindow,minScale=isMobile ? .5 : .6;if(fps<45&&renderScale>minScale){renderScale=Math.max(minScale,renderScale-.12);renderer.setPixelRatio(renderScale);renderer.setSize(innerWidth,innerHeight)}if(fps<32&&renderer.shadowMap.enabled)renderer.shadowMap.enabled=false;perfWindow=0;perfFrames=0}
}requestAnimationFrame(animate);
// Pause every sound and stop an active run when the page loses focus.
function pauseWhenLeaving(){audioSuspended=true;if(mode==='playing'&&!paused)togglePause();for(const audio of audioTracks)audio.pause()}
function resumeAudioOnReturn(){if(!document.hidden)audioSuspended=false}
document.addEventListener('visibilitychange',()=>{if(document.hidden)pauseWhenLeaving();else resumeAudioOnReturn()});window.addEventListener('blur',pauseWhenLeaving);window.addEventListener('focus',resumeAudioOnReturn);window.addEventListener('pagehide',pauseWhenLeaving);document.addEventListener('freeze',pauseWhenLeaving);
addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(renderScale)});
